test('shows the order total with tax', async ({ page }) => {
  await seedCart(page, [{ sku: 'A', price: 9.99, qty: 2 }, { sku: 'B', price: 4.5, qty: 1 }]);
  await page.goto('/checkout');
  // 24.48 subtotal + 12.3% tax
  await expect(page.getByTestId('order-total')).toHaveText('$27.50');
});
